/**
 * Template `init.json`: questions `init` asks, and string replacements
 * it applies while copying the scaffold.
 */
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { parseCursorGithubRepoScope } from "../channels/github/cursor-account.js";
import { describeError, describeErrorCode } from "./describe-error.js";
import { collectAnswers } from "./interview/question.js";
import { isRecord } from "./is-record.js";
export const TEMPLATE_INIT_FILE = "init.json";
export function posixRel(rel) {
    return rel.replaceAll("\\", "/");
}
export function isTemplateMetaPath(rel) {
    const normalized = posixRel(rel);
    const top = normalized.split("/")[0];
    if (top === "overlays") {
        return true;
    }
    return normalized === TEMPLATE_INIT_FILE || normalized.endsWith(`/${TEMPLATE_INIT_FILE}`);
}
export function templateFileHasReplacements(spec, rel) {
    const file = posixRel(rel);
    return spec.replace.some((rule) => posixRel(rule.file) === file);
}
export async function loadTemplateInitSpec(templateDir) {
    try {
        const text = await readFile(join(templateDir, TEMPLATE_INIT_FILE), "utf8");
        return parseTemplateInitSpec(JSON.parse(text));
    }
    catch (error) {
        if (describeErrorCode(error) === "ENOENT") {
            return undefined;
        }
        throw error;
    }
}
export function parseTemplateInitSpec(value) {
    if (!isRecord(value) || !Array.isArray(value.questions)) {
        throw new Error(`${TEMPLATE_INIT_FILE} must have a questions array`);
    }
    const questions = value.questions.map((item, index) => parseQuestion(item, index));
    const replace = Array.isArray(value.replace)
        ? value.replace.map((item, index) => parseReplace(item, index))
        : [];
    return { questions, replace };
}
export function parseInitVars(flags) {
    const vars = {};
    if (flags === undefined) {
        return vars;
    }
    for (const flag of flags) {
        const eq = flag.indexOf("=");
        if (eq <= 0) {
            throw new Error(`--var must be id=value (got ${JSON.stringify(flag)})`);
        }
        vars[flag.slice(0, eq)] = flag.slice(eq + 1);
    }
    return vars;
}
/** Load `init.json`, apply `--var`, and prompt on a TTY. */
export async function runTemplateInit(input) {
    try {
        const spec = await loadTemplateInitSpec(input.templateDir);
        if (spec === undefined) {
            return { ok: true };
        }
        const collected = await collectTemplateAnswers({
            spec,
            vars: parseInitVars(input.vars),
            interactive: input.interactive,
        });
        if (!collected.ok) {
            return collected;
        }
        return { ok: true, spec, answers: collected.answers };
    }
    catch (error) {
        return { ok: false, error: describeError(error) };
    }
}
const PARSERS = {
    "owner-repo-list": (value) => parseCursorGithubRepoScope(value.split(",").map((repo) => repo.trim())).repos.join(", "),
};
export async function collectTemplateAnswers(input) {
    const collected = await collectAnswers({
        questions: input.spec.questions.map((question) => ({
            ...question,
            parse: question.parse === undefined ? undefined : PARSERS[question.parse],
        })),
        given: input.vars,
        interactive: input.interactive,
        ask: input.ask,
        out: input.out,
    });
    return collected.ok ? { ok: true, answers: collected.answers } : collected;
}
export function applyInitReplacements(contents, rel, spec, answers) {
    const file = posixRel(rel);
    let next = contents;
    for (const rule of spec.replace) {
        if (posixRel(rule.file) !== file) {
            continue;
        }
        const value = formatReplaceValue(rule, answers);
        if (value === undefined) {
            continue;
        }
        if (!next.includes(rule.find)) {
            throw new Error(`${TEMPLATE_INIT_FILE}: ${rule.find} not found in ${rel}`);
        }
        next = replaceLiteral(next, rule.find, value);
    }
    return next;
}
function replaceLiteral(haystack, find, value) {
    return haystack.replaceAll(find, () => value);
}
function formatReplaceValue(rule, answers) {
    const raw = answers[rule.answer];
    if (raw === undefined || raw === "") {
        return undefined;
    }
    const parts = raw.split(",").map((part) => part.trim());
    let value = raw;
    if (rule.as === "json-array") {
        value = `[${parts.map((part) => JSON.stringify(part)).join(", ")}]`;
    }
    else if (rule.as === "first") {
        const first = parts[0];
        if (first === undefined || first === "") {
            return undefined;
        }
        value = first;
    }
    if (rule.template !== undefined) {
        return replaceLiteral(rule.template, "{{value}}", value);
    }
    return value;
}
function parseQuestion(value, index) {
    if (!isRecord(value) || typeof value.id !== "string" || value.id === "") {
        throw new Error(`${TEMPLATE_INIT_FILE} questions[${index}] needs an id`);
    }
    if (typeof value.prompt !== "string" || value.prompt === "") {
        throw new Error(`${TEMPLATE_INIT_FILE} questions[${value.id}] needs a prompt`);
    }
    const question = {
        id: value.id,
        prompt: value.prompt,
    };
    if (typeof value.hint === "string") {
        question.hint = value.hint;
    }
    if (typeof value.placeholder === "string") {
        question.placeholder = value.placeholder;
    }
    if (typeof value.default === "string") {
        question.default = value.default;
    }
    if (Array.isArray(value.choices)) {
        question.choices = value.choices.map((choice) => String(choice));
    }
    if (value.parse === "owner-repo-list") {
        question.parse = "owner-repo-list";
    }
    return question;
}
function parseReplace(value, index) {
    if (!isRecord(value) ||
        typeof value.file !== "string" ||
        value.file === "" ||
        typeof value.find !== "string" ||
        value.find === "" ||
        typeof value.answer !== "string" ||
        value.answer === "") {
        throw new Error(`${TEMPLATE_INIT_FILE} replace[${index}] needs file, find, and answer`);
    }
    const rule = {
        file: value.file,
        find: value.find,
        answer: value.answer,
    };
    if (value.as === "json-array" || value.as === "first") {
        rule.as = value.as;
    }
    if (typeof value.template === "string") {
        rule.template = value.template;
    }
    return rule;
}
